// A simple metadata container similar in spirit to NumPy's finfo,
// but with integer-only fields as requested.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FloatInfo {
    pub eps: u32,              // machine epsilon (smallest increment), > 0
    pub epsneg: u32,           // negative machine epsilon (smallest decrement), > 0
    pub max: u32,              // maximum representable value, > 0
    pub min: i32,              // minimum representable value, == -(max as i32)
    pub tiny: u32,             // smallest positive normal, > 0
    pub smallest_subnormal: u32, // smallest positive subnormal, > 0 and < tiny
    pub maxexp: i32,           // maximum exponent, > 0
    pub minexp: i32,           // minimum exponent, < 0
    pub negep: i32,            // exponent corresponding to epsneg, < 0
    pub exp_bits: u32,         // number of exponent bits, > 0
    pub mant_bits: u32,        // number of mantissa bits, > 0
    pub precision: u32,        // decimal precision approximation, 1..=mant_bits
}